const user = { name: 'Ada', address: { city: 'London' }, roles: ['admin', 'dev'] };

const { name, address: { city }, country = 'UK' } = user;
// name='Ada', city='London', country='UK'

const [primary, ...rest] = user.roles;
// primary='admin', rest=['dev']

function render({ title, size = 'md' }) {
  return `${title} (${size})`;
}
render({ title: 'Card' }); // 'Card (md)'

const original = { meta: { views: 1 } };

const shallow = { ...original };
shallow.meta.views = 99;
console.log(original.meta.views); // 99 — shared!

const deep = structuredClone(original);
deep.meta.views = 42;
console.log(original.meta.views); // 99 — untouched

JSON.parse(JSON.stringify({ d: new Date() })).d; // string, not Date!

const orders = [
  { id: 1, total: 120, status: 'paid' },
  { id: 2, total: 80, status: 'pending' },
  { id: 3, total: 45, status: 'paid' },
];

orders.filter(o => o.status === 'paid')
      .map(o => o.total)
      .reduce((sum, t) => sum + t, 0); // 165

// reduce building an object:
orders.reduce((acc, o) => {
  acc[o.status] = (acc[o.status] ?? 0) + 1;
  return acc;
}, {}); // { paid: 2, pending: 1 }
